style.css:
@-moz-document domain("youtube.com") {
/* ==============================
       ✦ CELESTIAL PURPLE YOUTUBE BAR ✦
       ============================== */

    /* Main progress bar */
    .ytp-play-progress {
        background: linear-gradient(
            90deg,
            #c9b6ff 0%,
            #d9caff 45%,
            #bda3ff 100%
        ) !important;

        box-shadow:
            0 0 4px #d8c7ff,
            0 0 9px #c4adff,
            0 0 15px rgba(190, 160, 255, 0.75) !important;
    }

    /* The little progress handle */
    .ytp-scrubber-button {
        background: #eee7ff !important;

        box-shadow:
            0 0 4px #ffffff,
            0 0 8px #d8c7ff,
            0 0 14px #b99aff,
            0 0 20px rgba(185, 154, 255, 0.8) !important;
    }

    /* Hover = brighter celestial glow */
    .ytp-progress-bar:hover .ytp-play-progress {
        background: linear-gradient(
            90deg,
            #d8c9ff,
            #eee8ff,
            #c5adff
        ) !important;

        box-shadow:
            0 0 6px #eee7ff,
            0 0 12px #d2bdff,
            0 0 22px rgba(190, 160, 255, 0.9) !important;
    }

    /* Buffer bar — subtle lavender instead of gray */
    .ytp-load-progress {
        background: rgba(194, 174, 235, 0.28) !important;
    }

    .ytp-load-progress div {
        background: rgba(215, 200, 250, 0.38) !important;
    }

    /* Progress bar background */
    .ytp-progress-list {
        background: rgba(70, 55, 95, 0.45) !important;
    }

   /* ✦ Golden celestial star ✦ */
.ytp-play-progress::after {
    content: "★";
    position: absolute;
    right: -5px;
    top: 50%;
    transform: translateY(-55%);

    color: #fff3a6;
    font-size: 8px;
    line-height: 1;

    text-shadow:
        0 0 3px #fffbe0,
        0 0 6px #ffe98a,
        0 0 10px #e5c76b,
        0 0 16px rgba(255, 220, 120, 0.85);

    pointer-events: none;
}

    /* Make the bar slightly softer/rounder */
    .ytp-progress-bar-container,
    .ytp-progress-bar {
        border-radius: 999px !important;
    }
}
